+function resourceMatches(ruleResource: string, requestResource: string): boolean {
+  if (ruleResource === "*") return true;
+  if (ruleResource.endsWith("/*")) {
+    const prefix = ruleResource.slice(0, -1);
+    return requestResource.startsWith(prefix) && requestResource.length > prefix.length;
+  }
+  return ruleResource === requestResource;
+}
+
+function roleMatches(ruleRole: string, requestRoles: string[]): boolean {
+  return ruleRole === "*" || requestRoles.includes(ruleRole);
+}
+
+function actionMatches(ruleAction: string, requestAction: string): boolean {
+  return ruleAction === "*" || ruleAction === requestAction;
+}
